import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function built from a combination of rotated elliptic,
    a sum of cosines, and a polynomial term to induce specific ELA characteristics.

    Formula:
    f(x) = a * elliptic(x) + b * cosine_sum(x) + c * polynomial(x)

    where:
    - elliptic(x) encourages elongation
    - cosine_sum(x) introduces local structure
    - polynomial(x) provides global structure and interaction.
    """
    a = 1.0
    b = 0.2
    c = 0.05

    def elliptic(x):
        return np.sum(np.power(10, np.arange(len(x)) / (len(x) - 1)) * x**2)

    def cosine_sum(x):
        return np.sum(np.cos(2 * np.pi * x))

    def polynomial(x):
        if len(x) < 2:
          return 0.0 # Avoid calling x[1] when the array has fewer than 2 dimensions.
        return x[0]**4 - x[0]**2 + x[1]**3 + x[0]*x[1]


    return a * elliptic(x) + b * cosine_sum(x) + c * polynomial(x)
